def transform(grid):
    # Each colored 3x3 tile emits colored rays from center along the gaps,
    # according to the cell's central marker. Marker color indicates the ray.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Tile centers inferred from 3x3 blocks with the surrounding color-2 frame
    for r in range(2, h, 5):
        for c in range(2, w, 5):
            marker = grid[r][c]
            if marker == 2 or marker == 0:
                continue
            # extend vertically and horizontally through zeros to nearest neighboring tile
            for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                    out[rr][cc] = marker
                    rr += dr; cc += dc
    return out
