def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # The diagram is a regular array of framed 5x5 tiles, spaced every 7 cells.
    # Join equal center-marker colors between neighboring tile centers across the zero gutters.
    rows=[r for r in range(h) if r%7==1 and r+2<h]
    cols=[c for c in range(w) if c%7==1 and c+2<w]
    for r0 in rows:
        r=r0+2
        for c0 in cols:
            c=c0+2
            if grid[r][c] in (0,4): continue
            for nc0 in cols:
                nc=nc0+2
                if nc0>c0 and nc0-c0==7 and grid[r][nc]==grid[r][c]:
                    for x in range(c+1,nc):
                        if grid[r][x]==0: out[r][x]=grid[r][c]
            for nr0 in rows:
                nr=nr0+2
                if nr0>r0 and nr0-r0==7 and grid[nr][c]==grid[r][c]:
                    for y in range(r+1,nr):
                        if grid[y][c]==0: out[y][c]=grid[r][c]
    return out
