def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Each tile has an interior marker. For each color marker, connect all
    # neighboring tile markers in the same row/column, filling only blank gaps.
    # Tile centers are found as cells not equal to the frame color, grouped by 3x3.
    centers=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in (0,2,4): continue
            # marker cells belong to a solid 3x3 interior; take its center
            if (r,c) not in seen:
                cells=[(rr,cc) for rr in range(max(0,r-2),min(h,r+3)) for cc in range(max(0,c-2),min(w,c+3)) if grid[rr][cc]==v]
                if len(cells)>=3:
                    rs=[x for x,y in cells]; cs=[y for x,y in cells]
                    cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
                    centers.append((cr,cc,v)); seen.update(cells)
    for r,c,v in centers:
        for dr,dc in ((0,1),(1,0)):
            rr,cc=r+dr,c+dc
            while rr<h and cc<w and grid[rr][cc]==0:
                ar,ac=rr+dr,cc+dc
                while ar<h and ac<w and grid[ar][ac]==0: ar+=dr; ac+=dc
                if ar<h and ac<w and grid[ar][ac]==v: out[rr][cc]=v
                rr+=dr; cc+=dc
    return out
PY
